def cmp_semver(a, b):
    def parse(v):
        v = v.strip().split('+', 1)[0]
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, None

        nums = []
        for part in core.split('.'):
            try:
                nums.append(int(part))
            except ValueError:
                nums.append(0)

        return nums, (pre.split('.') if pre is not None else None)

    def is_numeric(s):
        return bool(s) and all(c in '0123456789' for c in s)

    ca, pa = parse(a)
    cb, pb = parse(b)

    for i in range(max(len(ca), len(cb))):
        x = ca[i] if i < len(ca) else 0
        y = cb[i] if i < len(cb) else 0
        if x != y:
            return -1 if x < y else 1

    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1

    for i in range(max(len(pa), len(pb))):
        if i >= len(pa):
            return -1
        if i >= len(pb):
            return 1

        x, y = pa[i], pb[i]
        xn, yn = is_numeric(x), is_numeric(y)

        if xn and yn:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif xn != yn:
            return -1 if xn else 1
        else:
            if x != y:
                return -1 if x < y else 1

    return 0

