def parse_range(header, size):
    if isinstance(header, (bytes, bytearray)):
        try:
            header = header.decode("ascii")
        except UnicodeDecodeError:
            return None

    if not isinstance(header, str):
        return None

    try:
        size = int(size)
    except (TypeError, ValueError, OverflowError):
        return None

    if size < 0:
        return None

    header = header.strip()
    if not header.startswith("bytes="):
        return None

    value = header[6:].strip()
    if not value:
        return None

    def is_digits(s):
        return bool(s) and all(c in "0123456789" for c in s)

    ranges = []

    for part in value.split(","):
        part = part.strip()

        if part.count("-") != 1:
            return None

        start_s, end_s = part.split("-", 1)

        if not ((start_s == "" or is_digits(start_s)) and (end_s == "" or is_digits(end_s))):
            return None

        if start_s == "" and end_s == "":
            return None

        if start_s:
            start = int(start_s)

            if start >= size:
                continue

            if end_s:
                end = int(end_s)
                if end < start:
                    continue
                end = min(end, size - 1)
            else:
                end = size - 1
        else:
            suffix = int(end_s)

            if suffix == 0 or size == 0:
                continue

            start = max(size - suffix, 0)
            end = size - 1

        ranges.append((start, end))

    return ranges if ranges else None

