from decimal import Decimal, ROUND_HALF_EVEN, localcontext

def round_money(amount, places):
    quantum = Decimal((0, (1,), -places))
    with localcontext() as ctx:
        if amount.is_finite():
            t = amount.as_tuple()
            digits = len(t.digits)
            exponent = t.exponent
            ctx.prec = max(ctx.prec, digits + max(0, exponent + places) + 2)
        return amount.quantize(quantum, rounding=ROUND_HALF_EVEN)

